{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "Direct comparative evidence in patients with myasthenia gravis reports oral bioavailability of pyridostigmine, the query molecule, as 7.6%, which is below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Neostigmine, a closely related quaternary ammonium carbamate, had absolute oral bioavailability of 2.0 ± 0.33% in fasted myasthenic patients, supporting the expectation of low oral bioavailability for the permanently charged query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Rivastigmine, a structurally related carbamate but with a tertiary amine instead of a quaternary pyridinium, showed high absolute oral bioavailability (71.7%); this is contradictory in direction but has low transferability because the query's permanent positive charge is a major absorption barrier.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct evidence for pyridostigmine gives oral bioavailability ~7.6%, below the 20% threshold, and the closely related quaternary ammonium neostigmine also shows ~2% F. The permanent positive charge strongly impairs passive permeability, so low oral bioavailability is predicted despite high-F tertiary carbamate analogues.",
  "evidence_gaps": [
    "The direct pyridostigmine value is reported in a comparative context without full protocol details; a formal absolute bioavailability study under fasted conditions in healthy volunteers is not provided.",
    "No specific data on active transport, efflux, or gut-wall metabolism for the query molecule are available.",
    "The influence of salt form or formulation on the query's oral bioavailability is not addressed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

